	fmt.Fprintln(os.Stderr, `    update-domain: Update settings for the organization's custom domain`)
	fmt.Fprintln(os.Stderr, `    set-root-mcp-endpoint: Set or clear the MCP endpoint mapped to a custom domain's root`)
